<tr><td>Verifiability</td><td>+</td><td></td><td>+</td><td>+</td><td></td><td>+</td><td></td><td></td><td>+</td><td>+</td><td>+</td><td>+</td><td></td><td>+</td><td>+</td><td>■</td></tr>
